insert into public.activities (id, level_id, proverb, original, language, question, answers, correct, explanation, audio, xp, validated, sort) values
  ('prov-1-01', 'baoule-6', 'On ne balaie pas la cour avec une seule main.', null, null, 'Que veut dire ce proverbe ?', '["On a besoin des autres pour réussir.","Chacun doit s''occuper de sa propre part du travail.","Il vaut mieux bien faire une tâche que la faire vite.","Un travail bâclé se voit toujours."]'::jsonb, 0, 'La coopération rend les tâches plus faciles et plus solides.', null, 20, false, 0),
  ('prov-1-02', 'baoule-6', 'Une seule tête ne tient pas conseil.', null, null, 'Quelle idée se cache derrière ce proverbe ?', '["Les décisions importantes se prennent à plusieurs.","Le chef doit d''abord écouter sa propre sagesse.","Il ne faut pas trop réfléchir avant d''agir.","Celui qui parle seul n''est pas écouté."]'::jsonb, 0, 'Chez les Akan, le conseil réunit plusieurs voix : une décision partagée est plus sage.', null, 20, false, 1),
  ('prov-1-03', 'baoule-6', 'L''arbre seul face au vent se brise.', null, null, 'Que nous apprend ce proverbe ?', '["Isolé, on est plus fragile face aux difficultés.","Il faut savoir plier pour ne pas rompre.","Les difficultés finissent toujours par passer.","Celui qui se met en avant s''expose aux critiques."]'::jsonb, 0, 'Une forêt résiste au vent, un arbre seul casse : la communauté protège.', null, 20, false, 2),
  ('prov-1-04', 'baoule-6', 'Si tu veux aller vite, marche seul ; si tu veux aller loin, marchons ensemble.', null, null, 'Quel conseil donne ce proverbe ?', '["Seul on va vite, mais ensemble on va plus loin.","Il faut choisir entre la vitesse et la sécurité.","Les longs voyages demandent une bonne préparation.","Mieux vaut avancer seul que mal accompagné."]'::jsonb, 0, 'Les grands projets demandent du temps et des partenaires.', null, 20, false, 3),
  ('prov-1-05', 'baoule-6', 'Celui qui demande son chemin ne se perd pas.', null, null, 'Quelle idée se rapproche de ce proverbe ?', '["Demander de l''aide est une force.","Il faut toujours suivre le chemin de ses parents.","Celui qui connaît sa route n''a besoin de personne.","La prudence évite bien des erreurs."]'::jsonb, 0, 'Poser une question permet d''avancer avec plus de confiance.', null, 20, false, 4),
  ('prov-2-01', 'baoule-7', 'Ce qu''un vieillard voit assis, un jeune ne le voit pas debout.', null, null, 'Que veut dire ce proverbe ?', '["L''expérience des aînés permet de voir plus loin.","Les jeunes doivent rester debout devant les anciens.","La patience permet de mieux observer les choses.","Il faut se reposer pour avoir les idées claires."]'::jsonb, 0, 'Les années d''expérience donnent un regard que la jeunesse n''a pas encore.', null, 20, false, 5),
  ('prov-2-02', 'baoule-7', 'Personne ne montre Dieu à un enfant.', null, null, 'Quel est le sens de ce proverbe ?', '["Certaines vérités sont évidentes, même pour les plus jeunes.","La foi doit s''apprendre dès l''enfance.","Les enfants doivent respecter ce qui est sacré.","Les parents ne peuvent pas tout expliquer à leurs enfants."]'::jsonb, 0, 'Certaines choses n''ont pas besoin d''être enseignées : chacun les perçoit naturellement.', null, 20, false, 6),
  ('prov-2-03', 'baoule-7', 'Il n''est pas interdit de revenir chercher ce que l''on a oublié.', null, null, 'Ce proverbe est à l''origine du symbole Sankofa. Que signifie-t-il ?', '["On peut retourner à ses racines pour mieux avancer.","Il faut toujours vérifier qu''on n''a rien oublié.","On a le droit de changer d''avis.","Le passé est passé, il faut regarder devant."]'::jsonb, 0, 'Sankofa, l''oiseau qui regarde en arrière : connaître son passé aide à construire l''avenir.', null, 20, false, 7),
  ('prov-2-04', 'baoule-7', 'C''est dans les vieilles marmites qu''on fait les bonnes sauces.', null, null, 'Que veut dire cette expression ?', '["L''expérience et l''ancienneté donnent les meilleurs résultats.","Il faut garder les recettes des anciens.","Ce qui est simple est souvent le meilleur.","Il ne faut pas jeter ce qui peut encore servir."]'::jsonb, 0, 'On reconnaît la valeur de ce qui a fait ses preuves avec le temps.', null, 20, false, 8),
  ('prov-2-05', 'baoule-7', 'Quand un vieillard meurt, c''est une bibliothèque qui brûle.', null, null, 'Que veut transmettre cette phrase ?', '["Les savoirs des aînés disparaissent s''ils ne sont pas transmis.","Les aînés sont les gardiens des livres et des archives.","Il faut honorer les anciens après leur mort.","Le savoir écrit vaut plus que la parole."]'::jsonb, 0, 'Cette phrase, popularisée par Amadou Hampâté Bâ, rappelle l''urgence de transmettre les savoirs oraux.', null, 20, false, 9),
  ('prov-3-01', 'baoule-8', 'La parole est comme l''eau versée : on ne peut plus la ramasser.', null, null, 'Quel conseil donne ce proverbe ?', '["Il faut réfléchir avant de parler.","Une promesse doit toujours être tenue.","Les paroles s''oublient aussi vite qu''elles sont dites.","Il ne faut pas gaspiller ce qui est précieux."]'::jsonb, 0, 'Une parole dite ne se reprend pas : on mesure ses mots.', null, 20, false, 10),
  ('prov-3-02', 'baoule-8', 'Un tronc d''arbre a beau séjourner dans l''eau, il ne deviendra jamais crocodile.', null, null, 'Que veut dire ce proverbe ?', '["On ne change pas sa nature profonde.","Avec le temps, on finit par s''adapter à son milieu.","Il faut se méfier des apparences.","La patience ne suffit pas sans le talent."]'::jsonb, 0, 'On peut imiter les autres, mais on reste qui on est.', null, 20, false, 11),
  ('prov-3-03', 'baoule-8', 'Quand tu ne sais pas où tu vas, regarde d''où tu viens.', null, null, 'Quelle idée exprime ce proverbe ?', '["Connaître ses origines aide à trouver sa voie.","Quand on hésite, il vaut mieux faire demi-tour.","Il faut demander conseil avant de partir.","Il ne faut jamais quitter sa terre natale."]'::jsonb, 0, 'Nos racines sont une boussole quand l''avenir est flou.', null, 20, false, 12),
  ('prov-3-04', 'baoule-8', 'La patience est un arbre aux racines amères, mais aux fruits très doux.', null, null, 'Que nous apprend ce proverbe ?', '["Attendre est difficile, mais la récompense en vaut la peine.","Ce qui commence mal finit souvent mal.","Il faut savoir profiter des moments doux de la vie.","Le travail de la terre demande beaucoup de soins."]'::jsonb, 0, 'La patience coûte sur le moment, mais elle porte ses fruits.', null, 20, false, 13),
  ('prov-3-05', 'baoule-8', 'Le mensonge donne des fleurs, mais pas de fruits.', null, null, 'Quel est le sens de ce proverbe ?', '["Le mensonge peut sembler réussir, mais il ne mène à rien de durable.","Un beau discours vaut mieux qu''un long silence.","Les apparences reflètent souvent la réalité.","Un petit mensonge peut parfois rendre service."]'::jsonb, 0, 'Un mensonge peut briller un moment, il ne construit rien de solide.', null, 20, false, 14),
  ('nz-bci-01', 'baoule-9', 'L''être humain est meilleur que l''or.', 'srã ble ɔ ti kpa tra sika ɔklwɛ', 'Baoulé', 'Que veut dire ce proverbe ?', '["Une personne vaut plus que toutes les richesses.","La richesse finit toujours par se perdre.","Un homme honnête finit par devenir riche.","Il faut travailler dur pour gagner sa vie."]'::jsonb, 0, 'Chez les Baoulé, l''or est le bien le plus précieux, mais l''être humain vaut plus encore : on aime son prochain sans cupidité. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 15),
  ('nz-bci-02', 'baoule-9', 'L''amour appelle l''amour.', 'klolɛ flɛ klolɛ', 'Baoulé', 'Que veut dire ce proverbe ?', '["Celui qui aime les autres est aimé en retour.","L''amour se mérite par les cadeaux.","Il faut aimer sans rien attendre en retour.","Le véritable amour est rare."]'::jsonb, 0, 'Aimer les autres attire leur amour : si chacun aime, le monde se remplit d''amour. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 16),
  ('nz-bci-03', 'baoule-9', 'Le jour de ton prochain est aussi ton jour.', 'viégu i tchin ɔ ti ɔ liɛ', 'Baoulé', 'Que veut dire ce proverbe ?', '["Il faut être solidaire de ceux qui nous entourent.","Chaque jour apporte sa part de bonheur.","Il faut savoir attendre son tour.","Le temps passe pour tout le monde de la même façon."]'::jsonb, 0, 'Ce proverbe rappelle à l''ordre celui qui s''éloigne de la solidarité. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 17),
  ('nz-bci-04', 'baoule-9', 'Chaque arbre a ses fruits.', 'ɔ le baka kun ni ma', 'Baoulé', 'Que veut dire ce proverbe ?', '["Celui qui fait le bien en récoltera les fruits.","Il faut planter des arbres pour ses enfants.","Il ne faut pas convoiter ce qui appartient aux autres.","Tout finit par mûrir avec le temps."]'::jsonb, 0, 'Le bienfait n''est jamais perdu : celui qui fait le bien sera béni. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 18),
  ('nz-bci-05', 'baoule-9', 'Si on ne voit pas le cadavre, on ne fabrique pas son cercueil.', null, null, 'Que veut dire ce proverbe ?', '["Il ne faut pas juger quelqu''un sans le connaître.","Il faut respecter les morts.","Il vaut mieux croire ce que disent les autres.","Les mauvaises nouvelles arrivent toujours vite."]'::jsonb, 0, 'Ce proverbe combat les préjugés : on ne prête pas de défauts à quelqu''un sans avoir vécu avec lui. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 19),
  ('nz-bci-06', 'baoule-9', 'On n''emballe pas la vie dans une feuille de taro.', 'be kiti man koko gna nu', 'Baoulé', 'Que veut dire ce proverbe ?', '["La vie est précieuse, il faut la protéger.","Il ne faut pas confier ses secrets à n''importe qui.","Les choses simples sont souvent les plus solides.","Il faut bien choisir ses outils pour chaque travail."]'::jsonb, 0, 'La feuille de taro sèche et se déchire vite au soleil : on ne confie pas la vie, premier droit de chacun, à quelque chose d''aussi fragile. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 20),
  ('nz-bci-07', 'baoule-10', 'Les champignons ne poussent pas au faîte de l''arbre.', 'waka ti nu fí mã ŋdre', 'Baoulé', 'Que veut dire ce proverbe ?', '["Personne ne doit se placer au-dessus de l''autorité.","Chaque chose pousse à l''endroit qui lui convient.","Les plus petits sont souvent les plus utiles.","Il ne faut pas chercher la richesse trop loin."]'::jsonb, 0, 'L''enfant qui grandit à l''ombre de ses parents, dans le respect, profite de leurs conseils pour réussir. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 21),
  ('nz-bci-08', 'baoule-10', 'On n''exerce pas le pouvoir en ignorant les enfants.', null, null, 'Que veut dire ce proverbe ?', '["Ceux qui dirigent doivent tenir compte des jeunes.","Les enfants doivent apprendre à obéir aux chefs.","Un chef doit avoir une grande famille.","Le pouvoir se transmet de père en fils."]'::jsonb, 0, 'Le pouvoir des anciens se soucie de l''avenir de la nouvelle génération : les jeunes comptent. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 22),
  ('nz-bci-09', 'baoule-10', 'On ne fonde pas un campement avec quelqu''un avec qui on ne s''entend pas.', 'be ni srã be di mã be bo mã nãmwe', 'Baoulé', 'Que veut dire ce proverbe ?', '["Vivre et travailler ensemble demande de bien s''entendre.","Il faut bien choisir l''endroit où l''on s''installe.","On ne doit jamais quitter son village.","Chacun doit construire sa propre maison."]'::jsonb, 0, 'Un véritable appel à l''entente pour une vie sociale harmonieuse. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 23),
  ('nz-bci-10', 'baoule-10', 'Avant de te marier, renseigne-toi.', 'adja bisa', 'Baoulé', 'Que veut dire ce proverbe ?', '["Il faut bien connaître la personne avant de s''engager.","Il faut l''accord de ses parents pour se marier.","Le mariage doit se préparer longtemps à l''avance.","Il faut choisir un conjoint de sa région."]'::jsonb, 0, 'Prendre le temps de connaître le caractère de l''autre évite bien des unions difficiles. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 24),
  ('nz-bci-11', 'baoule-10', 'Le linge sale se lave en famille.', null, null, 'Que veut dire ce proverbe ?', '["On règle d''abord ses différends en famille, avant de les exposer.","Il faut garder sa maison propre et rangée.","On ne doit jamais parler de sa famille aux autres.","Les tâches ménagères se partagent en famille."]'::jsonb, 0, 'On ne saute pas d''étape : chef de famille, chef de village, chef de canton, puis roi. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 25),
  ('nz-bci-12', 'baoule-11', 'Si tu ne te fatigues pas, tu ne riras pas.', 'a fɛ mã a sri mã', 'Baoulé', 'Que veut dire ce proverbe ?', '["Pour connaître le bonheur, il faut travailler.","Il faut savoir se reposer pour profiter de la vie.","Le rire est le meilleur remède à la fatigue.","Ceux qui travaillent trop oublient de rire."]'::jsonb, 0, 'Celui qui veut jouir du bonheur doit se mettre au travail. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 26),
  ('nz-bci-13', 'baoule-11', 'C''est la personne qui creuse dans la termitière qui a la poitrine rouge.', 'srã mɔ ɔ fu srwe jɛ i wue ɔ blo', 'Baoulé', 'Que veut dire ce proverbe ?', '["Celui qui mérite les honneurs se reconnaît à ses efforts.","Le travail de la terre abîme le corps.","Il faut se protéger avant un travail difficile.","Les honneurs reviennent toujours aux plus âgés."]'::jsonb, 0, 'La terre rouge de la termitière colore la poitrine de celui qui creuse : ses exploits se voient. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 27),
  ('nz-bci-14', 'baoule-11', 'Si tu déterres l''igname, recouvre les racines du manioc avec de la terre.', 'sè a tu duo kata agba bo', 'Baoulé', 'Que veut dire ce proverbe ?', '["Il faut protéger les ressources pour les générations futures.","Il faut finir un travail avant d''en commencer un autre.","Il faut récolter chaque culture au bon moment.","Il faut aider son voisin dans ses champs."]'::jsonb, 0, 'Une image tirée des champs pour appeler à préserver la nature et en faire profiter ceux qui viendront après. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 28),
  ('nz-bci-15', 'baoule-11', 'Là où on garde sa poterie d''huile, on n''y lance pas des pierres.', 'lika nga be ŋgo sɛ ɔ o lɛ be to mã lɛ jɔbu', 'Baoulé', 'Que veut dire ce proverbe ?', '["On ne fait pas de mal à ce qui nous fait vivre.","Il faut ranger ses biens précieux en lieu sûr.","La colère fait perdre ce qu''on a de plus cher.","Il ne faut pas se disputer devant les enfants."]'::jsonb, 0, 'Lancer des pierres casserait les poteries et ferait perdre l''huile : on prend soin de sa communauté et de son pays. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 29),
  ('nz-bci-16', 'baoule-11', 'C''est quand il y a la paix au village qu''il peut y avoir la paix en brousse.', null, null, 'Que veut dire ce proverbe ?', '["La paix commence en famille avant de s''étendre à toute la société.","Le village est plus sûr que la brousse.","Il faut faire la paix avec la nature.","Quand tout va bien au village, on peut partir en voyage."]'::jsonb, 0, 'Le village, c''est la famille ; la brousse, toute la société : s''entendre avec les siens permet de s''entendre avec les autres. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 30),
  ('nz-bci-17', 'baoule-11', 'Le pardon est le dernier mot.', null, null, 'Que veut dire ce proverbe ?', '["Il faut savoir pardonner pour mettre fin aux conflits.","Celui qui parle en dernier a toujours raison.","Il faut attendre que l''autre s''excuse en premier.","Un conflit se règle par la parole des anciens."]'::jsonb, 0, 'Il n''y a plus rien à dire à celui qui refuse le pardon : les sages poussent ainsi à la réconciliation. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 31),
  ('nz-sen-01', 'senoufo-6', 'Quand le doigt fait mal, l''œil n''a pas sommeil.', 'kabani kana ja ɲɛ̃pini ko bãna wunɔ̃i', 'Sénoufo', 'Que veut dire ce proverbe ?', '["Il faut être solidaire de ceux qui souffrent.","Une petite douleur peut empêcher de dormir.","Il faut soigner un problème avant qu''il grandisse.","Il faut rester vigilant la nuit."]'::jsonb, 0, 'L''amour du prochain pousse à aider ceux qui sont en difficulté : le vrai bonheur est partagé. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 32),
  ('nz-sen-02', 'senoufo-6', 'Sur la tête du méchant, il ne pousse pas de cornes.', null, null, 'Que veut dire ce proverbe ?', '["La méchanceté n''apporte ni honneur ni dignité.","Les méchants finissent toujours punis.","Il faut se méfier de ceux qui se vantent.","La force ne fait pas le chef."]'::jsonb, 0, 'Les cornes symbolisent l''autorité, la dignité et l''honneur : le méchant n''est ni béni ni élevé. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 33),
  ('nz-sen-03', 'senoufo-6', 'Il ne faut pas demander au sel d''être sucré.', 'faɡa jasɔɡi jeɡi tɛ̃nɛ̃ sikaʀawi dɛlɛi', 'Sénoufo', 'Que veut dire ce proverbe ?', '["Il faut accepter les autres dans leur différence.","Chaque plat a sa recette.","Il faut savoir doser les choses.","La vérité est parfois difficile à entendre."]'::jsonb, 0, 'Exiger de l''autre qu''il soit ce qu''il n''est pas crée des conflits : chacun est utile à sa façon, comme le sel dans la sauce. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 34),
  ('nz-sen-04', 'senoufo-6', 'L''enfant obéissant ne meurt pas de faim.', 'kateʔe ko pi lowe kui', 'Sénoufo', 'Que veut dire ce proverbe ?', '["Écouter ses parents apporte des avantages.","Un enfant doit apprendre à se nourrir seul.","Les parents doivent d''abord nourrir leurs enfants.","Il faut partager sa nourriture avec les enfants."]'::jsonb, 0, 'Les parents sont ceux qui trouvent la nourriture : l''obéissance ne produit que des avantages. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 35),
  ('nz-sen-05', 'senoufo-6', 'L''homme est mieux que l''argent.', null, null, 'Que veut dire ce proverbe ?', '["Les personnes passent avant l''argent.","Un homme travailleur gagne toujours de l''argent.","Il vaut mieux prêter de l''argent qu''en emprunter.","Un homme se juge à sa richesse."]'::jsonb, 0, 'Les Sénoufo font primer l''humanité en toute circonstance (les Baoulé disent de même : « l''être humain est meilleur que l''or »). Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 36),
  ('nz-sen-06', 'senoufo-7', 'Le criquet est seul dans son trou, mais il n''est pas le seul sous l''arbre.', null, null, 'Que veut dire ce proverbe ?', '["Le chef décide en concertation avec les sages.","Chacun est seul face à ses problèmes.","Les petits ont aussi leur place dans la communauté.","Il faut sortir de chez soi pour se faire des amis."]'::jsonb, 0, 'Le criquet, c''est le chef : il paraît seul car les décisions sont prises en son nom, mais il a le soutien des notables et des sages. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 37),
  ('nz-sen-07', 'senoufo-7', 'La femme d''un tel est belle, cela ne veut pas dire qu''elle a bon caractère.', 'wɔ̃ co wu ɲɔ̃ ɡiɡe j̄o we fuɡi ɲɔ̃i', 'Sénoufo', 'Que veut dire ce proverbe ?', '["La vraie beauté est celle du comportement.","Il ne faut pas envier la femme d''un autre.","La beauté se transmet de mère en fille.","Il faut écouter les compliments avec méfiance."]'::jsonb, 0, 'La beauté physique peut tromper : les Sénoufo conseillent de se fier à la beauté intérieure. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 38),
  ('nz-sen-08', 'senoufo-7', 'Le matin, les oiseaux s''envolent, mais le soir, ils reviennent tous au nid.', 'ɲiɡidãni fij̄ãɡele nalali cãɡi ɡakɔ ɡolugo ɡezaʀi mã', 'Sénoufo', 'Que veut dire ce proverbe ?', '["On peut partir chercher ailleurs, mais il faut revenir à ses racines.","Il faut se lever tôt pour réussir.","Il faut rentrer chez soi avant la nuit.","Les enfants finissent toujours par quitter leurs parents."]'::jsonb, 0, 'Le matin est le temps de la recherche, le soir celui du retour : l''expatrié qui revient enrichit son pays. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 39),
  ('nz-sen-09', 'senoufo-7', 'Dieu s''appuie sur toi-même pour t''aider.', 'kolocɔlɔ sewe siʔi mu na bu mu dɛbɛ', 'Sénoufo', 'Que veut dire ce proverbe ?', '["Il faut faire des efforts pour réussir.","Il faut aider les autres comme Dieu nous aide.","La prière suffit pour obtenir ce qu''on veut.","Dieu aide d''abord ceux qui sont dans le besoin."]'::jsonb, 0, 'Garder espoir, mais redoubler d''efforts : l''effort favorise la réussite. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 40),
  ('nz-sen-10', 'senoufo-7', 'C''est celui qui a tué la panthère qui doit avoir la tête rasée.', null, null, 'Que veut dire ce proverbe ?', '["Les honneurs reviennent à celui qui a vraiment excellé.","Les chasseurs doivent respecter les animaux.","Il faut finir ce qu''on a commencé.","Celui qui prend des risques doit en payer le prix."]'::jsonb, 0, 'Chez les Sénoufo, on honore le chasseur dozo qui a tué une panthère en lui rasant la tête : le mérite se reconnaît. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 41),
  ('nz-sen-11', 'senoufo-7', 'Les chefs n''arrangent pas leurs palabres devant l''assemblée.', 'kaʔa fɔbele ko be kasi cɔ̃ʀi kaʔa sibele jɛmai', 'Sénoufo', 'Que veut dire ce proverbe ?', '["Les conflits entre responsables se règlent avec discrétion.","Les chefs doivent rendre la justice en public.","Un chef ne doit jamais se disputer.","Les palabres doivent être réglées par les anciens."]'::jsonb, 0, 'Régler les différends loin des regards préserve le respect et évite les tensions. Source : Touman Kouadio H., « Proverbes et culture : le cas des proverbes baoulé et sénoufo de Côte d''Ivoire », revue Nzassa, Université Alassane Ouattara.', null, 20, false, 42),
  ('afro-bev-01', 'bete-6', 'Lorsque l''œil pleure, le nez ne se réjouit pas.', null, null, 'Que veut dire ce proverbe ?', '["Le malheur d''une personne touche aussi ses proches.","Il ne faut pas montrer sa tristesse aux autres.","Les larmes finissent toujours par sécher.","On ne peut pas être heureux quand on est malade."]'::jsonb, 0, 'Le malheur de quelqu''un touche aussi ses parents et ses amis. Source : Dr Y., afrolegends.com.', null, 20, false, 43),
  ('afro-bev-02', 'bete-6', 'Quand le doigt ne sait où aller, il entre dans le nez.', null, null, 'Que veut dire ce proverbe ?', '["Trop d''inactivité pousse à faire des bêtises.","Quand on ne sait pas quoi faire, il faut demander conseil.","Les mauvaises habitudes commencent dès l''enfance.","Il faut savoir où l''on va avant de partir."]'::jsonb, 0, 'Trop d''inactivité conduit à n''importe quelle bêtise. Source : Dr Y., afrolegends.com.', null, 20, false, 44),
  ('afro-bev-03', 'bete-6', 'Les doigts de la main n''ont pas la même longueur.', null, null, 'Que veut dire ce proverbe ?', '["Les hommes ne sont pas tous égaux.","Il faut unir ses forces comme les doigts de la main.","Les aînés doivent passer avant les jeunes.","Il ne faut pas comparer ses enfants entre eux."]'::jsonb, 0, 'Les hommes ne sont jamais égaux. Source : Dr Y., afrolegends.com.', null, 20, false, 45),
  ('zoko-bev-01', 'bete-6', 'Seul son coiffeur peut toucher la tête du roi.', null, null, 'Que veut dire ce proverbe ?', '["Pour obtenir quelque chose de quelqu''un, il faut d''abord gagner sa confiance.","Seuls les proches peuvent critiquer un chef.","Il faut respecter le corps du roi.","Chaque métier a ses privilèges."]'::jsonb, 0, 'Pour profiter de quelqu''un, il faut d''abord gagner son amitié. Source : Habib Zoko, Proverbes ivoiriens chez les Bétés.', null, 20, false, 46),
  ('zoko-bev-02', 'bete-6', 'Tu donnes des conseils au renard, donnes-en aussi à la poule.', null, null, 'Que veut dire ce proverbe ?', '["Celui qui est en danger doit aussi être prudent.","Il ne faut pas faire confiance aux rusés.","Il faut écouter les deux camps avant de juger.","Les conseils ne servent à rien aux méchants."]'::jsonb, 0, 'Le renard mange les poules : la poule, elle, ne doit pas s''éloigner de chez elle. Source : Habib Zoko, Proverbes ivoiriens chez les Bétés.', null, 20, false, 47),
  ('cma-q-bci-01', 'baoule-12', 'Masque portrait mblo', null, null, 'Quand sortent les masques mblo ?', '["Lors de danses de divertissement","Lors des funérailles","Pour l''initiation des garçons","Pour rendre la justice"]'::jsonb, 0, 'Les masques mblo, très appréciés des Baoulé, sortent lors de danses de divertissement. Ils sont vus comme les portraits de personnes connues. Source : The Cleveland Museum of Art (Open Access). Voir la fiche dans la Bibliothèque.', null, 20, false, 48),
  ('cma-q-bci-02', 'baoule-12', 'Pendentifs en or baoulé', null, null, 'À quoi les objets en or sont-ils liés chez les Baoulé ?', '["Aux esprits des ancêtres","Au mariage","À la royauté seulement","À la protection des récoltes"]'::jsonb, 0, 'Les objets en or sont les seules œuvres baoulé liées aux esprits des ancêtres. On les sort lors des grandes occasions, comme les funérailles. Source : The Cleveland Museum of Art (Open Access). Voir la fiche dans la Bibliothèque.', null, 20, false, 49),
  ('cma-q-bci-03', 'baoule-12', 'Pendentifs en or baoulé', null, null, 'Avec quelle technique ces pendentifs sont-ils coulés ?', '["La cire perdue","Le martelage à froid","Le filage de l''or","Le moulage dans le sable"]'::jsonb, 0, 'L''orfèvre façonne le modèle en cire ; la cire fond dans un moule où l''on verse ensuite l''or liquide. Source : The Cleveland Museum of Art (Open Access). Voir la fiche dans la Bibliothèque.', null, 20, false, 50),
  ('cma-q-bci-04', 'baoule-12', 'Pendentif au front marqué « ngwa »', null, null, 'Que signifie « ngwa », la marque en croissant sur le front ?', '["La lune","Le soleil","L''étoile du matin","La rivière"]'::jsonb, 0, 'La scarification en forme de croissant sur le front s''appelle ngwa, la « lune ». Source : The Cleveland Museum of Art (Open Access). Voir la fiche dans la Bibliothèque.', null, 20, false, 51),
  ('cma-q-bci-05', 'baoule-12', 'Couple de statuettes asye usu', null, null, 'Que représentent souvent les statuettes baoulé sculptées par paires ?', '["Des esprits de la brousse","Des ancêtres de la famille","Des jumeaux","Un roi et une reine"]'::jsonb, 0, 'Elles représentent souvent les asye usu, esprits de la brousse ; on les sculpte belles et parées pour les séduire. Source : The Cleveland Museum of Art (Open Access). Voir la fiche dans la Bibliothèque.', null, 20, false, 52),
  ('cma-q-bci-06', 'baoule-12', 'Masque kplé kplé', null, null, 'Dans quelle danse le masque kplé kplé apparaît-il en premier ?', '["La danse goli","Le zaouli","L''abissa","Le boloye"]'::jsonb, 0, 'Le kplé kplé ouvre la danse goli, où quatre paires de masques se succèdent ; il est porté par de jeunes garçons. Source : The Cleveland Museum of Art (Open Access). Voir la fiche dans la Bibliothèque.', null, 20, false, 53),
  ('cma-q-bci-07', 'baoule-12', 'Poulie de métier à tisser', null, null, 'À quoi sert une poulie de métier à tisser ?', '["À soutenir et séparer les fils","À enrouler le fil filé","À tasser les fils tissés","À teindre les bandes de tissu"]'::jsonb, 0, 'Placée au-dessus du tisserand, la poulie soutient les fils ; on la décore d''une sculpture agréable à regarder. Source : The Cleveland Museum of Art (Open Access). Voir la fiche dans la Bibliothèque.', null, 20, false, 54),
  ('cma-q-sen-01', 'senoufo-8', 'Maternité sénoufo', null, null, 'Dans la société sénoufo, par qui l''héritage se transmet-il ?', '["Par les femmes (lignée maternelle)","Par le fils aîné","Par le chef du bois sacré","Par les forgerons"]'::jsonb, 0, 'La maternité des ancêtres est centrale chez les Sénoufo, où l''héritage se transmet par les femmes. Source : The Cleveland Museum of Art (Open Access). Voir la fiche dans la Bibliothèque.', null, 20, false, 55),
  ('cma-q-sen-02', 'senoufo-8', 'Maternité sénoufo', null, null, 'Comment s''appelle la Grande Mère qui nourrit les initiés du « lait du savoir » ?', '["Katyeleeo (ou Maleeo)","Abla Pokou","Mami Wata","Yaa Asantewaa"]'::jsonb, 0, 'Pour certains Sénoufo, la Grande Mère Katyeleeo, ou Maleeo, nourrit les jeunes initiés du « lait du savoir ». Source : The Cleveland Museum of Art (Open Access). Voir la fiche dans la Bibliothèque.', null, 20, false, 56),
  ('cma-q-sen-03', 'senoufo-8', 'Casque sénoufo', null, null, 'Ce casque marquait le passage d''un garçon à une nouvelle classe d''âge, avant son initiation à…', '["Le Poro","Le Sandogo","Le Goli","Le Dipri"]'::jsonb, 0, 'Ce casque était porté lors des rituels de passage d''une classe d''âge à l''autre, avant l''initiation au Poro. Source : The Cleveland Museum of Art (Open Access). Voir la fiche dans la Bibliothèque.', null, 20, false, 57),
  ('cma-q-sen-04', 'senoufo-8', 'Oiseau-trophée sénoufo', null, null, 'À qui remettait-on l''oiseau-trophée ?', '["Au vainqueur d''un concours de culture à la houe","Au meilleur chasseur","Au meilleur danseur","Au plus jeune initié"]'::jsonb, 0, 'Le bâton surmonté de l''oiseau récompense le vainqueur d''un concours de culture entre jeunes hommes. Source : The Cleveland Museum of Art (Open Access). Voir la fiche dans la Bibliothèque.', null, 20, false, 58),
  ('cma-q-sen-05', 'senoufo-8', 'Oiseau-trophée sénoufo', null, null, 'Quel oiseau est représenté sur ce trophée ?', '["Un aigle en vol","Un calao","Un hibou","Un vautour"]'::jsonb, 0, 'Le trophée représente un aigle en vol, qui surmontait un long bâton. Source : The Cleveland Museum of Art (Open Access). Voir la fiche dans la Bibliothèque.', null, 20, false, 59)
insert into public.challenges (id, role, unlock_after_level, title, description, reward_xp, duration_min, difficulty, steps, note_prompt, sort) values
  ('jeune-proverbe-famille', 'jeune', 'baoule-6', 'Le proverbe de ma famille', 'Demande à un aîné de ton entourage un proverbe qu''on disait dans sa famille.', 100, 15, 'Facile', '["Choisis un aîné de ton entourage : grand-parent, oncle, tante, voisin…","Demande-lui un proverbe qu''on disait dans sa famille.","Demande-lui ce qu''il veut dire et quand on l''utilise.","Note le proverbe et son sens ci-dessous."]'::jsonb, 'Le proverbe et son sens', 0),
  ('jeune-jeux-autrefois', 'jeune', 'baoule-7', 'Les jeux d''autrefois', 'Découvre à quoi jouait un aîné quand il avait ton âge.', 100, 20, 'Facile', '["Demande à un aîné à quoi il jouait quand il était enfant.","Fais-toi expliquer les règles du jeu.","Essayez d''y jouer ensemble, même quelques minutes.","Note le nom du jeu et ce que tu as appris."]'::jsonb, 'Le nom du jeu et ses règles', 1),
  ('jeune-geste-numerique', 'jeune', 'baoule-8', 'Un geste numérique', 'Apprends à un aîné à envoyer un message vocal sur son téléphone.', 120, 15, 'Moyen', '["Assieds-toi avec un aîné et son téléphone.","Montre-lui comment enregistrer et envoyer un message vocal.","Laisse-le essayer seul pendant que tu l''encourages.","Demande-lui de t''envoyer un proverbe en vocal."]'::jsonb, 'Comment ça s''est passé ?', 2),
  ('senior-transmets-proverbe', 'senior', 'baoule-6', 'Transmets un proverbe', 'Partage avec un jeune un proverbe qu''on disait dans votre famille.', 100, 15, 'Facile', '["Choisis un jeune de ton entourage : petit-enfant, neveu, voisin…","Partage-lui un proverbe de ta famille.","Explique-lui ce qu''il veut dire et quand on l''utilise.","Note le proverbe et son sens ci-dessous."]'::jsonb, 'Le proverbe et son sens', 3),
  ('senior-raconte-jeu', 'senior', 'baoule-7', 'Raconte un jeu d''autrefois', 'Apprends à un jeune un jeu de ton enfance.', 100, 20, 'Facile', '["Pense à un jeu de ton enfance.","Explique ses règles à un jeune.","Jouez-y ensemble quelques minutes.","Note le nom du jeu et ses règles."]'::jsonb, 'Le nom du jeu et ses règles', 4),
  ('senior-geste-numerique', 'senior', 'baoule-8', 'Apprends un geste numérique', 'Demande à un jeune de t''apprendre à envoyer un message vocal.', 120, 15, 'Moyen', '["Demande à un jeune de t''aider avec ton téléphone.","Fais-toi montrer comment enregistrer un message vocal.","Essaie seul, il est là pour t''aider.","Envoie-lui un proverbe en vocal."]'::jsonb, 'Comment ça s''est passé ?', 5)
